-- ========================================================




-- ========================================================

function CatFootStep:__init()
    self.controller = nil
    self.isInit = false
end

function CatFootStep:__delete()
end




function CatFootStep:Init( followTF_, isHide_ )
    KTool.SetActive(self.controller.gameObject, true);
    self.transform = self.controller.gameObject.transform
    -- ==============================
    -- 绑定 Update() 函数:
    local behaviourAction = KTool.GetOrAddComponent(self.controller.gameObject, typeof(BehaviourAction))
    if behaviourAction then
        behaviourAction.UpdateAction = function(behaviourAction)
            self:Update()
        end
    end

    assert( self.walkFX and self.runFX and self.jumpStartFX and self.jumpEndFX  )
    assert( isNotNull(followTF_) )
    self.followTF = followTF_
    
    ----------------------------------
    -- frames: 
    -- <0: idle 状态, 不处理
    --  0: 走完倒计时的最后一帧, 需要处理 state
    -- >0: 倒计时

    self.fxs = {}
    self.fxs.walk      = { frames = 0, tgtActive = false, gameObj = self.walkFX.gameObject }
    self.fxs.run       = { frames = 0, tgtActive = false, gameObj = self.runFX.gameObject }
    self.fxs.jumpStart = { frames = 0, tgtActive = false, gameObj = self.jumpStartFX.gameObject }
    self.fxs.jumpEnd   = { frames = 0, tgtActive = false, gameObj = self.jumpEndFX.gameObject }

    self.isHide = isHide_
    if self.isHide == true then 
        for k,fx in pairs(self.fxs) do 
            KTool.SetActive( fx.gameObj, false )
        end
    end 

    self.isInit = true
end



function CatFootStep:OnDestroy()
    self.controller = nil --删除lua层引用到的c#对象 否则不会产生c# gc回收到对象
    self:Delete()
end



function CatFootStep:Update()
    if self.isInit ~= true then 
        return
    end 
    if self.isHide == true then 
        return
    end 

    self.transform.position = self.followTF.position
    self.transform.rotation = self.followTF.rotation

    for k,fx in pairs(self.fxs) do 

        if fx.frames == 0 then 
            KTool.SetActive( fx.gameObj, fx.tgtActive )
        end 
        
        if fx.frames >= 0 then 
            fx.frames = fx.frames - 1
        end
    end
end



-- =========================================== Self ================================================ --


function CatFootStep:WhenPlayerMoveStateChanged( currentFootStepState_, oldFootStepState )
    if self.isInit ~= true then 
        return
    end 
    if self.isHide == true then 
        return
    end 

    local ShowEnum = function( e_ )
        if e_ == FootStepState.Idle then 
            return "Idle"
        elseif e_ == FootStepState.Walk  then
            return "Walk";
        elseif e_ == FootStepState.Run  then
            return "Run";
        elseif e_ == FootStepState.JumpStart  then
            return "JumpStart";
        elseif e_ == FootStepState.JumpEnd  then
            return "JumpEnd";
        else
            assert( false, "类型异常: " .. tostring(e_) )
            return "";
        end
    end

    -- 发生切换时:
    if currentFootStepState_ ~= oldFootStepState then 
        
        if currentFootStepState_ == FootStepState.Idle then 
            -- Idle --:
            -- 一定会从 walk, run 进入 idle: JumpEnd 后不会进入 Idle
            --print( ShowEnum(oldFootStepState) .. " --> Idle" )

            self:SetFXs( self.fxs.walk,      false,  0.5 )
            self:SetFXs( self.fxs.run,       false,  0.5 )

            self:SetFXs( self.fxs.jumpStart, false )
            self:SetFXs( self.fxs.jumpEnd,   false )


        elseif currentFootStepState_ == FootStepState.Walk then
            -- Walk --:
            --print( ShowEnum(oldFootStepState) .. " --> Walk" )

            self:SetFXs( self.fxs.run,       false, (oldFootStepState == FootStepState.Run) and 0.4 or 0.0 )
            self:SetFXs( self.fxs.walk,      true,  0.0 )

            self:SetFXs( self.fxs.jumpStart, false )
            self:SetFXs( self.fxs.jumpEnd,   false )


        elseif currentFootStepState_ == FootStepState.Run then
            -- Run --:
            --print( ShowEnum(oldFootStepState) .. " --> Run" )

            self:SetFXs( self.fxs.walk,      false,  (oldFootStepState == FootStepState.Walk) and 0.4 or 0.0 )
            self:SetFXs( self.fxs.run,       true,  0.0 )

            self:SetFXs( self.fxs.jumpStart, false )
            self:SetFXs( self.fxs.jumpEnd,   false )


        elseif currentFootStepState_ == FootStepState.JumpStart then
            -- JumpStart --:
            -- walk, run 在进入 JumpStart 之前, 一定会先进入 idle:
            --print( ShowEnum(oldFootStepState) .. " --> JumpStart" )

            self:SetFXs( self.fxs.walk,      false,  0.0 )
            self:SetFXs( self.fxs.run,       false,  0.0 )

            self:SetFXs( self.fxs.jumpStart, true )
            self:SetFXs( self.fxs.jumpEnd,   false )

            -- 播放 猫 jumpStart 声音:
            -- The audio clip of 'jumpstart' is not used for now.


        elseif currentFootStepState_ == FootStepState.JumpEnd then
            -- JumpEnd --:
            -- 一定由 JumpStart 后接 JumpEnd, JumpEnd 之后一定接 Walk 或 run;
            --print( ShowEnum(oldFootStepState) .. " --> JumpEnd" )

            self:SetFXs( self.fxs.walk,      false,  0.0 )
            self:SetFXs( self.fxs.run,       false,  0.0 )

            self:SetFXs( self.fxs.jumpStart, false )
            self:SetFXs( self.fxs.jumpEnd,   true )

            
            -- 播放 猫 jumpEnd 声音:
            if (DreamSpaceStates.floorMaterial == DreamSpaceStates.FloorMaterials.Default) then
                DreamSpaceSounds.Play( DreamSpaceSounds.sfx.catLandMetal )
            else
                DreamSpaceSounds.Play( DreamSpaceSounds.sfx.catLandGlass )
            end


        else
            assert( false, "参数异常: " )
        end
    end
end



function CatFootStep:SetFXs( fxObj_, isActive_, time_ )
    local t = checkNumber(time_)
    fxObj_.frames = checkInt( t / Time.deltaTime ) -- 一个粗略的帧数, 但基本够用 
    fxObj_.tgtActive = isActive_
end 



return CatFootStep

